import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t,o,c as e,a3 as l}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/18-忧边第十二.md","filePath":"books/yan-tie-lun/18-忧边第十二.md","lastUpdated":1784092560000}'),_={name:"books/yan-tie-lun/18-忧边第十二.md"};function n(s,a,i,r,c,d){return o(),e("div",null,[...a[0]||(a[0]=[l('<p>忧边第十二 【题解】</p><p>本篇辩论的主题又回归到边境费用问题之上。大夫强调盐铁官营、酒类专卖、均输平准都是为了补助边境费用，他批评文学关于废除盐铁官营的建议，认为文学不体恤边塞将士，不是边防将士的慈父贤兄。他说征召文学、贤良议政，本来是希望从中获取有益的建议，谁知文学、贤良的主张不上天就入地，根本不切实际。大夫还从孝义立论，认为盐铁官营等政策都是汉武帝旧政，嗣主不应该改变君父政策。文学坚持修文德以来远的立场，认为只要对匈奴“加之以德，施之以惠，北夷必内向，款塞自至，然后以为胡制于外臣，即匈奴没齿不食其所用矣”。显然，这只是文学的一种美好理想。</p><p>大夫曰：“文学言：‘天下不平，庶国不宁，明王之忧也。’故王者之于天下，犹一室之中也，有一人不得其所，则谓之不乐[(1)]。故民流溺而弗救[(2)]，非惠君也[(3)]。国家有难而不忧，非忠臣也。夫守节死难者，人臣之职也；衣食饥寒者，慈父之道也。今子弟远劳于外[(4)]，人主为之夙夜不宁，群臣尽力毕议[(5)]，册滋国用[(6)]。故少府丞令请建酒榷[(7)]，以赡边[(8)]，给战士[(9)]，拯民于难也。为人父兄者，岂可以已乎[(10)]！内省衣食以恤在外者，犹未足，今又欲罢诸用[(11)]，减奉边之费，未可为慈父贤兄也。”</p><p>【注释】</p><p>[(1)]谓：通“为”。</p><p>[(2)]流溺：受到水淹，比喻处于水深火热之中。一说，流，古代通“沉”。“流”下原有“沉”字，据王先谦说校删。</p><p>[(3)]惠君：仁惠之君。</p><p>[(4)]今子弟远劳于外：“劳于”原作“于劳”，据孙诒让、黄侃、郭沫若说校改。子弟，指边塞将士。</p><p>[(5)]毕议：都来讨论。毕，尽。</p><p>[(6)]册：通“策”，策划。滋：增加。国用：国家财政收入。</p><p>[(7)]少府丞令：少府是汉代九卿之一，掌山海池泽收入和皇室手工业制造，少府丞令是少府的属官。建酒榷：建立酒类专卖。</p><p>[(8)]赡边：补足边境费用。</p><p>[(9)]给战士：供给战斗将士。</p><p>[(10)]已：止，此处指不闻不问。</p><p>[(11)]罢诸用：指废除盐铁官营、酒类专卖、均输平准。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“文学说过：‘天下不太平，各诸侯国不安宁，这是英明君王的忧虑。’因此君王之于天下民众，如同住在一室之中的家人，如果室内有一个人不得其所，君王便为此闷闷不乐。因此，民众处于水深火热之中而不去拯救，就不能算仁惠之君。国家有难而不感到忧虑，就不是忠臣。坚守气节，为国死难，是人臣的职责。给饥寒的儿女提供衣食，这是做一个慈父的道理。如今战士们在边塞征战劳苦，皇上为此日夜不能安宁，群臣尽力议论，策划增加国家财政收入。因此少府属官请求建立酒类专卖，以便补足边境费用，供给前方战斗将士，从灾难中拯救民众。作为他人的父兄，岂可以不闻不问！在家里节省衣食以救济在外的战士，尚且不够，如今你们又想废除盐铁官营、酒类专卖、均输平准，减少供给边境费用，你们不能算是慈父贤兄。”</p><p>文学曰：“周之季末[(1)]，天子微弱，诸侯力政[(2)]，故国君不安，谋臣奔驰。何者？敌国众而社稷危也。今九州同域[(3)]，天下一统，陛下优游岩廊[(4)]，览群臣极言至论[(5)]，内咏《雅》、《颂》，外鸣和銮[(6)]，纯德粲然[(7)]，并于唐、虞[(8)]，功烈流于子孙[(9)]。夫蛮、貊之人，不食之地[(10)]，何足以烦虑，而有战国之忧哉？若陛下不弃，加之以德，施之以惠，北夷必内向[(11)]，款塞自至[(12)]，然后以为胡制于外臣[(13)]，即匈奴没齿不食其所用矣[(14)]。”</p><p>【注释】</p><p>[(1)]季末：季世，末世。</p><p>[(2)]力政：力征，武力征讨。政，通“征”。</p><p>[(3)]九州：《尚书·禹贡》载禹治水成功之后，将中国划分为九州——冀州、兖州、青州、徐州、扬州、荆州、豫州、梁州、雍州。同域：同在中国疆域之内。</p><p>[(4)]优游：悠闲自在。岩廊：高廊，指朝廷宫殿。</p><p>[(5)]览群臣极言至论：原作“览群极言至内论雅、颂”，据张敦仁说校改。极言至论，奏章上的恳切言论。</p><p>[(6)]和銮：鸾鸟形状的铃铛。和銮是天子安乐的象征。</p><p>[(7)]纯德粲然：纯美的德行光辉灿烂。</p><p>[(8)]并于唐、虞：意谓功德可与唐尧、虞舜相提并论。</p><p>[(9)]功烈：功业。</p><p>[(10)]不食之地：犹言不毛之地，形容荒凉。</p><p>[(11)]北夷：指匈奴。内向：向中国归服。</p><p>[(12)]款塞：敲开边塞之门。</p><p>[(13)]制：控制。外臣：塞外之臣。</p><p>[(14)]没齿：到老。食：反悔。用：为，行为。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“周朝末世，天子力量微弱，诸侯互相以武力征讨，因此各国君主为之不安，谋臣纷纷奔走游说。为什么呢？敌国众多而社稷危险。如今九州同在一个中国，天下一统，陛下在宫殿内悠闲自在，浏览群臣奏章上的恳切言论，在宫内吟咏《雅》、《颂》，在宫外乘坐铃铛和鸣的马车，纯美的德行光辉灿烂，与唐尧、虞舜相提并论，功业流传到后代子孙。那些蛮荒异族，不毛之地，有什么值得烦恼焦虑，而有战国时期的忧患呢？如果陛下不嫌弃，赐予恩德，施加仁惠，那么匈奴一定会内向中国，敲开塞门，自己来朝归附。然后把匈奴当做塞外之臣加以控制，这样匈奴就到老也不会后悔他们归顺的行为了。”</p><p>大夫曰：“圣主思中国之未宁，北边之未安，使故廷尉评等问人间所疾苦[(1)]。拯恤贫贱[(2)]，周赡不足[(3)]。群臣所宣明王之德[(4)]，安宇内者[(5)]，未得其纪[(6)]，故问诸生。诸生议不干天则入渊[(7)]，乃欲以闾里之治[(8)]，而况国家之大事[(9)]，亦不几矣[(10)]！发于畎亩[(11)]，出于穷巷，不知冰水之寒[(12)]，若醉而新寤，殊不足与言也。”</p><p>【注释】</p><p>[(1)]使故：原作“故使”，据王利器说校改。故，此前任此官，现不在任者。廷尉：西汉时期掌管司法的官吏。《汉书·昭帝纪》：“始元六年闰月，遣故廷尉王平等五人，持节行郡国，举贤良，问民所疾苦冤失职者。”平，通“评”。</p><p>[(2)]拯恤：救助。</p><p>[(3)]周瞻：接济。</p><p>[(4)]群：原作“君”，据张敦仁说校改。宣：宣布，传播。</p><p>[(5)]安宇内：安定天下。</p><p>[(6)]纪：要领。</p><p>[(7)]不干天则入渊：不上天就入地，比喻不切实际。干，接触。</p><p>[(8)]闾里之治：治理乡村的办法。</p><p>[(9)]而：以。况：比况。</p><p>[(10)]几：近。</p><p>[(11)]畎（quǎn）亩：田间，田地，指农村。</p><p>[(12)]不知冰水之寒：此句似有脱文。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“圣明君主思考中国尚未安宁，北部边境未能安定，委派前任廷尉王平等人慰问民间疾苦。帮助贫贱民众，接济衣食不足的人。群臣所宣扬英明君王的圣德，安抚天下，尚未得到要领，因此询问诸位儒生。诸位儒生的建议不上天就入地，想用治理乡村的办法，来比况国家大事，这也太不近情理了！来自农村，出于穷巷，如同夏蝉不知冬天冰水的寒冷，好像喝醉了酒刚刚醒过来一样，根本不值得与你们讨论。”</p><p>文学曰：“夫欲安民富国之道，在于反本，本立而道生[(1)]。顺天之理，因地之利，即不劳而功成。夫不修其源而事其流[(2)]，无本以统之，虽竭精神，尽思虑，无益于治。欲安之适足以危之，欲救之适足以败之。夫治乱之端，在于本末而已，不至劳其心而道可得也。孔子曰：‘不通于论者难于言治[(3)]，道不同者，不相与谋[(4)]。’今公卿意有所倚[(5)]，故文学之言，不可用也。”</p><p>【注释】</p><p>[(1)]本立而道生：《论语·学而》：“君子务本，本立而道生。”结合上文，文学所说的“本”，应该是修治文德。</p><p>[(2)]源、流：意同本、末。</p><p>[(3)]不通于论：不明道理。</p><p>[(4)]道不同者，不相与谋：《论语·卫灵公》：“道不同，不相与谋。”</p><p>[(5)]倚：借作“踦”，偏。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“希望安民富国的途径，在于返回根本，根本确立了，路径就形成了。顺应天理，遵循地利，就不必劳苦而大功告成。如果不追寻源头而抓末流，缺乏根本来统领，即使竭尽精神，耗尽思虑，对于治国也是无益。希望安定却恰恰带来危险，希望拯救却恰恰带来失败。国家治乱的关键，在于分清根本与末枝而已，不必劳心就可以得到治国之道。孔子说：‘不明道理的人很难与他讨论治国，信奉不同治国道理的人，不能在一起互相商量国家大事。’如今公卿思想有所偏向，因而文学的主张，不被公卿采纳。”</p><p>大夫曰：“吾闻为人臣者尽忠以顺职，为人子者致孝以承业。君有非，则臣覆盖之[(1)]。父有非，则子匿逃之[(2)]。故君薨[(3)]，臣不变君之政，父没，则子不改父之道也[(4)]。《春秋》讥毁泉台[(5)]，为其隳先祖之所为[(6)]，而扬君父之恶也。今盐铁、均输，所从来久矣，而欲罢之，得无害先帝之功，而妨圣主之德乎[(7)]？有司倚于忠孝之路，是道殊而不同于文学之谋也。”</p><p>【注释】</p><p>[(1)]覆盖：掩盖。</p><p>[(2)]匿逃：隐匿。</p><p>[(3)]薨（hōnɡ）：诸侯去世叫薨。《礼记·曲礼下》：“天子死曰崩，诸侯死曰薨。”</p><p>[(4)]父没，则子不改父之道也：《论语·学而》：“父在，观其志；父没，观其行；三年无改于父之道，可谓孝矣。”</p><p>[(5)]泉台：春秋时期鲁庄公所建的台阁，后被鲁文公拆毁。《春秋公羊传·文公十六年》认为鲁文公折毁泉台，是显扬先祖过恶，故予以讥刺。</p><p>[(6)]隳（huī）：毁坏。</p><p>[(7)]圣主：指汉昭帝刘弗陵。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“我听说作为人臣应该尽忠尽职，作为人子应该尽孝来继承父业。君主有过失，臣下应该予以掩盖。父亲有过失，儿子应该予以隐匿。因此君主去世，臣下不改变君主的政策。父亲去世，儿子不改变父亲的主张。《春秋公羊传·文公十六年》讥刺鲁文公拆毁鲁庄公建筑的泉台，因为鲁文公毁坏先祖所建泉台，是在宣扬君父的过恶。如今盐铁官营和均输，由来已久，你们却想废除，岂不是要妨害已故武帝的功业，而伤害当今圣明君主的仁德吗？主管官员偏向于忠孝之路，这就是由于我们道路不同，所以与文学的主张不同。”</p><p>文学曰：“明者因时而变，知者随世而制[(1)]。孔子曰：‘麻冕，礼也，今也纯，俭，吾从众。’[(2)]故圣人上贤不离古[(3)]，顺俗而不偏宜[(4)]。鲁定公序昭穆[(5)]，顺祖祢[(6)]，昭公废卿士[(7)]，以省事节用，不可谓变祖之所为，而改父之道也？二世充大阿房以崇绪[(8)]，赵高增累秦法以广威[(9)]，而未可谓忠臣孝子也。”</p><p>【注释】</p><p>[(1)]知：同“智”。随世而制：随当世情况而制定措施。</p><p>[(2)]麻冕，礼也，今也纯，俭，吾从众：见于《论语·子罕》。麻冕，用麻布织的礼帽。纯，用丝料制的礼帽。</p><p>[(3)]上：同“尚”。</p><p>[(4)]偏宜：偏向迎合时宜。</p><p>[(5)]鲁定公：春秋时期鲁国国君。序：排列次序。昭穆：古代的宗庙制度。祭祀时，始祖庙居中，以下是父为昭，子为穆。昭居左，穆居右。公元前625年，鲁文公举行祭礼时，将鲁僖公排在鲁闵公上面。依照昭穆制度，鲁僖公应列在鲁闵公的右边。鲁文公把次序颠倒，是一种逆祀。到公元前502年，鲁定公才把这个颠倒了的次序再颠倒过来。</p><p>[(6)]顺祖祢（mí）：理顺祖庙的昭穆关系。祖，祖庙。弥，父庙。</p><p>[(7)]昭公废卿士：公元前537年，鲁昭公废掉鲁襄公设置的中军卿士。昭公，春秋时期鲁国君主。</p><p>[(8)]二世：秦二世胡亥。充大：扩建。阿房：阿房宫。崇绪：继承秦始皇功业。</p><p>[(9)]增累：增设。广威：提高权威。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“聪明的人根据时势而变化，智慧的人随当世情况而制定措施。《论语·子罕》载孔子曰：‘礼帽用麻料来织，这是合于礼规的，今天大家都用丝料，这样省俭些，我同意大家做法。’因此圣人崇尚贤德不离开古礼，顺应时俗而不偏向迎合时宜。鲁定公重新排列祖庙的昭穆次序，理顺祖庙位置；鲁昭公废掉鲁襄公设置的中军卿士，以便减少事务，节省费用，这不能说是改变了祖先的行为，背离了父辈的成规。秦二世胡亥扩建阿房宫以继承秦始皇功业，赵高增设秦朝法令以提高自己权威，他们都不能算忠臣孝子。”</p>',90)])])}const f=t(_,[["render",n]]);export{u as __pageData,f as default};
